export interface PinmapInput {
  readonly map: PinMap;
  readonly mcu: StMcu;
}

function checkMcuConfig(spec: CircuitSpec, ctx: BuildContext): PartLabel | null {
  if (spec.mcu === null && ctx.pinmap !== null) throw new Error("a pin map was given but the circuit names no MCU");
  if (spec.mcu === null) return null;
  if (ctx.pinmap === null) throw new Error(`circuit names MCU ${spec.mcu.label} but no pin map was given`);
  const label = spec.mcu.label;
  if (!spec.parts.some((p) => p.label === label)) throw new Error(`circuit names MCU ${label}, which is not a part`);
  return label;
}

if (isMcu && ctx.pinmap !== null) {
  const { map, mcu } = ctx.pinmap;
  for (const a of map.assignments) {
    const st = mcu.pins.get(a.pin);
    if (st === undefined) throw new Error(`pin map assigns ${a.pin}, which ${mcu.refName} does not have; run pnpm pinmap validate`);
    const prior = declared.get(st.position);
    if (prior !== undefined) {
      const where = prior.net === null ? "as not connected" : `on net ${prior.net}`;
      throw new Error(
        `${p.label} pin ${st.position} (${a.pin}) is declared in the circuit ${where} and assigned by the pin map to ${a.net}; ` +
          "pinmap.json is authoritative for MCU pins — remove it from the circuit",
      );
    }
    declared.set(st.position, { part: p.label, pin: st.position, unit: unitFor(st.position), identity: a.pin, net: a.net, origin: "pinmap" });
  }
}

const big = (pins: PartSpec["pins"], ncAll: boolean): PartSpec => ({
  label: "U_MCU", refPrefix: "U", libId: "Fix:BIG8", units: [1], value: "BIG8", footprint: "F", bom: TEST_BOM,
  dnp: false, checklist: [], source: "t", pinTable: null, pins, mechanicalPads: [],
  ncUnlisted: ncAll ? { reason: "CORE-27" } : null,
});

const PINMAP: PinmapInput = {
  map: { mcu: "BIG8", pinData: "x", gpioModes: "y", schematicRef: "U1", assignments: [{ pin: "PA0", signal: "GPIO", net: "SIG", purpose: "p" }] },
  mcu: { refName: "BIG8", pins: new Map([["PA0", { port: "PA0", position: "1", signals: new Set<string>(), af: new Map<string, number>() }]]) },
};

it("merges pin-map assignments onto the MCU by package position, with the port as identity", () => {
  const c = buildCircuit(spec([big({}, true), res("R_1", "SIG", "GND")], true), { symbols, pinmap: PINMAP });
  const p1 = c.pins.find((p) => p.part === "U_MCU" && p.pin === "1");
  expect(p1).toEqual({ part: "U_MCU", pin: "1", unit: 1, identity: "PA0", net: "SIG", origin: "pinmap" });
});

it("refuses an MCU pin declared in the circuit and assigned by the pin map", () => {
  const declared = big({ "1": { net: "OTHER", identity: "D0" } }, true);
  expect(() => buildCircuit(spec([declared, res("R_1", "SIG", "GND")], true), { symbols, pinmap: PINMAP })).toThrow(
    /U_MCU pin 1 \(PA0\) is declared in the circuit on net OTHER and assigned by the pin map to SIG; pinmap.json is authoritative/,
  );
});

it("expands ncUnlisted to every remaining symbol pin, identity from the symbol", () => {
  const c = buildCircuit(spec([big({}, true), res("R_1", "SIG", "GND")], true), { symbols, pinmap: PINMAP });
  const nc = c.pins.filter((p) => p.part === "U_MCU" && p.origin === "nc-unlisted");
  expect(nc.map((p) => [p.pin, p.identity, p.net])).toEqual([
    ["2", "D1", null], ["3", "CLK", null], ["4", "GND", null], ["5", "CS", null], ["6", "D2", null], ["7", "NC", null], ["8", "VCC", null],
  ]);
});

it("refuses a pin map without an MCU and an MCU without a pin map", () => {
  expect(() => buildCircuit(spec([big({}, true)], false), { symbols, pinmap: PINMAP })).toThrow(/pin map was given but the circuit names no MCU/);
  expect(() => buildCircuit(spec([big({}, true)], true), { symbols, pinmap: null })).toThrow(/circuit names MCU U_MCU but no pin map was given/);
});
